#include <iostream>
#include <vector>

int find_nth_number(int n) {
    if (n < 0) return -1; // 예외 처리
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    std::vector<int> sequence = {0, -1, -1};
    for (int i = 3; i <= n; ++i) {
        int next_number = sequence[i - 1] + sequence[i - 2] + sequence[i - 3];
        sequence.push_back(next_number);
    }
    return sequence[n];
}

int main() {
    int n;
    std::cout << "숫자를 입력하세요: ";
    std::cin >> n;

    if (n < 0) {
        std::cout << "잘못된 입력입니다. 양수를 사용하세요." << std::endl;
    } else {
        std::cout << "n번째 숫자: " << find_nth_number(n) << std::endl;
    }
    return 0;
}
